def smallest_change(arr):
    if not all(isinstance(x, int) for x in arr):
        raise ValueError("Input array must contain only integers")

    n = len(arr)
    if n == 0:
        return 0

    mid = n // 2
    changes = 0

    for i in range(mid):
        if arr[i] != arr[n - i - 1]:
            changes += 1

    return changes

